DEFAULT_IMAGEPACKS_DIR = r"C:/Users/ThinkPad/Documents/GitHub/degrees-of-lewdity-plus/imagepacks"


def is_same_path_on_this_os(a: Path, b: Path) -> bool:
    """Return True when two paths are equivalent on the current filesystem rules."""
    return os.path.normcase(os.path.abspath(a)) == os.path.normcase(os.path.abspath(b))


def strip_img_prefix(rel_path: str) -> str:
    """Convert img/body/foo.png -> body/foo.png for packs that omit the img folder."""
    parts = Path(rel_path).parts
    if parts and parts[0].lower() == "img":
        return str(Path(*parts[1:]))
    return rel_path


def choose_layout(pack_root: Path, mode: str) -> tuple[str, bool]:
    """Return a human label and whether to strip leading img/ from RENAMES."""
    if mode == "with-img":
        return "pack/img/...", False
    if mode == "without-img":
        return "pack/...", True

    # auto mode: most DoL packs use imagepacks/<pack>/img/..., but some loose packs
    # store the body/clothes/etc folders directly inside the pack root.
    if (pack_root / "img").is_dir():
        return "pack/img/...", False
    return "pack/...", True


def rename_one(src: Path, dst: Path, dry_run: bool) -> str:
    """Rename one file. Returns: renamed, missing, exists, or error."""
    if not src.exists():
        return "missing"

    dst.parent.mkdir(parents=True, exist_ok=True) if not dry_run else None

    # Important on Windows: dst.exists() can be true for case-only renames like
    # StormBack.png -> stormBack.png. Treat that as the same file and do a safe
    # two-step rename through a temporary filename.
    if dst.exists():
        if is_same_path_on_this_os(src, dst) and str(src) != str(dst):
            if dry_run:
                return "renamed"

            tmp = src.with_name(src.name + ".__rename_tmp__")
            counter = 0
            while tmp.exists():
                counter += 1
                tmp = src.with_name(f"{src.name}.__rename_tmp__{counter}")

            src.rename(tmp)
            tmp.rename(dst)
            return "renamed"

        return "exists"

    if dry_run:
        return "renamed"

    src.rename(dst)
    return "renamed"


def process_pack(pack_root: Path, dry_run: bool, mode: str, verbose: bool) -> dict[str, int | str]:
    layout_label, strip_img = choose_layout(pack_root, mode)
    stats = {
        "pack": pack_root.name,
        "layout": layout_label,
        "renamed": 0,
        "missing": 0,
        "exists": 0,
        "error": 0,
    }

    for src_rel, dst_rel in RENAMES:
        if strip_img:
            src_rel_used = strip_img_prefix(src_rel)
            dst_rel_used = strip_img_prefix(dst_rel)
        else:
            src_rel_used = src_rel
            dst_rel_used = dst_rel

        src = pack_root / src_rel_used
        dst = pack_root / dst_rel_used

        try:
            result = rename_one(src, dst, dry_run)
        except Exception as exc:
            stats["error"] += 1
            print(f"ERROR [{pack_root.name}]: {src_rel_used} -> {dst_rel_used}: {exc}")
            continue

        if result == "renamed":
            stats["renamed"] += 1
            if verbose:
                print(f"  [{pack_root.name}] {src_rel_used} -> {dst_rel_used}")
        elif result == "missing":
            stats["missing"] += 1
        elif result == "exists":
            stats["exists"] += 1

    return stats


def main():
    parser = argparse.ArgumentParser(
        description="Apply DoL img rename table to every direct folder inside imagepacks."
    )
    parser.add_argument(
        "imagepacks_dir",
        nargs="?",
        default=DEFAULT_IMAGEPACKS_DIR,
        help=f"Path to imagepacks folder. Default: {DEFAULT_IMAGEPACKS_DIR}",
    )
    parser.add_argument("--dry-run", action="store_true", help="Print what would be renamed without moving files.")
    parser.add_argument("--verbose", action="store_true", help="Print each rename, not just per-pack totals.")
    parser.add_argument(
        "--layout",
        choices=["auto", "with-img", "without-img"],
        default="auto",
        help="Pack layout. auto uses pack/img if present, otherwise pack root directly.",
    )
    args = parser.parse_args()

    imagepacks_dir = Path(args.imagepacks_dir)
    if not imagepacks_dir.is_dir():
        raise SystemExit(f"Imagepacks folder not found: {imagepacks_dir}")

    packs = sorted(p for p in imagepacks_dir.iterdir() if p.is_dir())
    if not packs:
        raise SystemExit(f"No direct subfolders found in: {imagepacks_dir}")

    if args.dry_run:
        print("DRY RUN — no files will be moved./n")

    print(f"Imagepacks folder: {imagepacks_dir}")
    print(f"Packs found: {len(packs)}")
    print(f"Layout mode: {args.layout}/n")

    total = {"renamed": 0, "missing": 0, "exists": 0, "error": 0}

    for pack in packs:
        stats = process_pack(pack, args.dry_run, args.layout, args.verbose)
        for key in total:
            total[key] += int(stats[key])

        label = "Would rename" if args.dry_run else "Renamed"
        print(
            f"[{stats['pack']}] {stats['layout']} | "
            f"{label}: {stats['renamed']} | "
            f"missing: {stats['missing']} | "
            f"destination exists: {stats['exists']} | "
            f"errors: {stats['error']}"
        )

    label = "Would rename" if args.dry_run else "Renamed"
    print("/nTOTAL")
    print(f"{label}: {total['renamed']}")
    print(f"Skipped, source missing: {total['missing']}")
    print(f"Skipped, destination exists: {total['exists']}")
    print(f"Errors: {total['error']}")


if __name__ == "__main__":
    main()
